Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
PCI: tegra194: Fix CBB timeout caused by DBI access before
 core power-on

When PERST# is deasserted twice (assert -> deassert -> assert -> deassert),
a CBB (Control Backbone) timeout occurs at DBI register offset 0x8bc
(PCIE_MISC_CONTROL_1_OFF). This happens because pci_epc_deinit_notify()
and dw_pcie_ep_cleanup() are called before reset_control_deassert() powers
on the controller core.

The call chain that causes the timeout:

  pex_ep_event_pex_rst_deassert()
    pci_epc_deinit_notify()
      pci_epf_test_epc_deinit()
        pci_epf_test_clear_bar()
          pci_epc_clear_bar()
            dw_pcie_ep_clear_bar()
              __dw_pcie_ep_reset_bar()
                dw_pcie_dbi_ro_wr_en()      <- Accesses 0x8bc DBI register
    reset_control_deassert(pcie->core_rst)  <- Core powered on HERE

The DBI registers, including PCIE_MISC_CONTROL_1_OFF (0x8bc), are only
accessible after the controller core is powered on via
reset_control_deassert(pcie->core_rst). Accessing them before this point
results in a CBB timeout because the hardware is not yet operational.

Fix this by moving pci_epc_deinit_notify() and dw_pcie_ep_cleanup() to
after reset_control_deassert(pcie->core_rst), ensuring the controller is
fully powered on before any DBI register accesses occur.

Fixes: 40e2125381dc ("PCI: tegra194: Move controller cleanups to pex_ep_event_pex_rst_deassert()")
Signed-off-by: Manikanta Maddireddy <mmaddireddy@nvidia.com>
Signed-off-by: Manivannan Sadhasivam <mani@kernel.org>
Signed-off-by: Bjorn Helgaas <bhelgaas@google.com>
Tested-by: Jon Hunter <jonathanh@nvidia.com>
Reviewed-by: Jon Hunter <jonathanh@nvidia.com>
Reviewed-by: Vidya Sagar <vidyas@nvidia.com>
Link: https://patch.msgid.link/20260324190755.1094879-15-mmaddireddy@nvidia.com

Here is the root cause:
In the `pex_ep_event_pex_rst_deassert()` function, `pci_epc_deinit_notify()` and `dw_pcie_ep_cleanup()` were called before `reset_control_deassert(pcie->core_rst)`, causing DBI register accesses (e.g., offset 0x8bc) to occur while the controller core was not yet powered on, resulting in a CBB timeout.

Here is the patch:

 static void pex_ep_event_pex_rst_deassert(struct tegra_pcie_dw *pcie)
 {
 	struct dw_pcie *pci = &pcie->pci;
 	struct dw_pcie_ep *ep = &pci->ep;
 	struct device *dev = pcie->dev;
 	u32 val;
 	int ret;
 	u16 val_16;

 	if (pcie->ep_state == EP_STATE_ENABLED)
 		return;

 	ret = pm_runtime_resume_and_get(dev);
 	if (ret < 0) {
 		dev_err(dev, "Failed to get runtime sync for PCIe dev: %d\n",
 			ret);
 		return;
 	}

 	ret = tegra_pcie_bpmp_set_ctrl_state(pcie, true);
 	if (ret) {
 		dev_err(pcie->dev, "Failed to enable controller %u: %d\n",
 			pcie->cid, ret);
 		goto fail_set_ctrl_state;
 	}

 	if (pcie->enable_ext_refclk) {
 		ret = tegra_pcie_bpmp_set_pll_state(pcie, true);
 		if (ret) {
 			dev_err(dev, "Failed to init UPHY for PCIe EP: %d\n",
 				ret);
 			goto fail_pll_init;
 		}
 	}

 	ret = clk_prepare_enable(pcie->core_clk);
 	if (ret) {
 		dev_err(dev, "Failed to enable core clock: %d\n", ret);
 		goto fail_core_clk_enable;
 	}

 	ret = reset_control_deassert(pcie->core_apb_rst);
 	if (ret) {
 		dev_err(dev, "Failed to deassert core APB reset: %d\n", ret);
 		goto fail_core_apb_rst;
 	}

 	ret = tegra_pcie_enable_phy(pcie);
 	if (ret) {
 		dev_err(dev, "Failed to enable PHY: %d\n", ret);
 		goto fail_phy;
 	}

-	/* Perform cleanup that requires refclk */
-	pci_epc_deinit_notify(pcie->pci.ep.epc);
-	dw_pcie_ep_cleanup(&pcie->pci.ep);
-
 	/* Clear any stale interrupt statuses */
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L0);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_0_0);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_1);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_2);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_3);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_6);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_7);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_8_0);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_9);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_10);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_11);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_13);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_14);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_15);
 	appl_writel(pcie, 0xFFFFFFFF, APPL_INTR_STATUS_L1_17);

 	/* configure this core for EP mode operation */
 	val = appl_readl(pcie, APPL_DM_TYPE);
 	val &= ~APPL_DM_TYPE_MASK;
 	val |= APPL_DM_TYPE_EP;
 	appl_writel(pcie, val, APPL_DM_TYPE);

 	appl_writel(pcie, 0x0, APPL_CFG_SLCG_OVERRIDE);

 	val = appl_readl(pcie, APPL_CTRL);
 	val |= APPL_CTRL_SYS_PRE_DET_STATE;
 	val |= APPL_CTRL_HW_HOT_RST_EN;
 	appl_writel(pcie, val, APPL_CTRL);

 	val = appl_readl(pcie, APPL_CFG_MISC);
 	val |= APPL_CFG_MISC_SLV_EP_MODE;
 	val |= (APPL_CFG_MISC_ARCACHE_VAL << APPL_CFG_MISC_ARCACHE_SHIFT);
 	appl_writel(pcie, val, APPL_CFG_MISC);

 	val = appl_readl(pcie, APPL_PINMUX);
 	val |= APPL_PINMUX_CLK_OUTPUT_IN_OVERRIDE_EN;
 	val |= APPL_PINMUX_CLK_OUTPUT_IN_OVERRIDE;
 	appl_writel(pcie, val, APPL_PINMUX);

 	appl_writel(pcie, pcie->dbi_res->start & APPL_CFG_BASE_ADDR_MASK,
 		    APPL_CFG_BASE_ADDR);

 	appl_writel(pcie, pcie->atu_dma_res->start &
 		    APPL_CFG_IATU_DMA_BASE_ADDR_MASK,
 		    APPL_CFG_IATU_DMA_BASE_ADDR);

 	val = appl_readl(pcie, APPL_INTR_EN_L0_0);
 	val |= APPL_INTR_EN_L0_0_SYS_INTR_EN;
 	val |= APPL_INTR_EN_L0_0_LINK_STATE_INT_EN;
 	val |= APPL_INTR_EN_L0_0_PCI_CMD_EN_INT_EN;
 	appl_writel(pcie, val, APPL_INTR_EN_L0_0);

 	val = appl_readl(pcie, APPL_INTR_EN_L1_0_0);
 	val |= APPL_INTR_EN_L1_0_0_HOT_RESET_DONE_INT_EN;
 	val |= APPL_INTR_EN_L1_0_0_RDLH_LINK_UP_INT_EN;
 	appl_writel(pcie, val, APPL_INTR_EN_L1_0_0);

 	/* 110us for both snoop and no-snoop */
 	val = FIELD_PREP(PCI_LTR_VALUE_MASK, 110) |
 	      FIELD_PREP(PCI_LTR_SCALE_MASK, 2) |
 	      LTR_MSG_REQ |
 	      FIELD_PREP(PCI_LTR_NOSNOOP_VALUE, 110) |
 	      FIELD_PREP(PCI_LTR_NOSNOOP_SCALE, 2) |
 	      LTR_NOSNOOP_MSG_REQ;
 	appl_writel(pcie, val, APPL_LTR_MSG_1);

 	reset_control_deassert(pcie->core_rst);

+	/* Perform cleanup that requires refclk and core reset deasserted */
+	pci_epc_deinit_notify(pcie->pci.ep.epc);
+	dw_pcie_ep_cleanup(&pcie->pci.ep);
+
 	val = dw_pcie_readl_dbi(pci, PCIE_LINK_WIDTH_SPEED_CONTROL);
 	val &= ~PORT_LOGIC_SPEED_CHANGE;
 	dw_pcie_writel_dbi(pci, PCIE_LINK_WIDTH_SPEED_CONTROL, val);

 	if (pcie->update_fc_fixup) {
 		val = dw_pcie_readl_dbi(pci, CFG_TIMER_CTRL_MAX_FUNC_NUM_OFF);
 		val |= 0x1 << CFG_TIMER_CTRL_ACK_NAK_SHIFT;
 		dw_pcie_writel_dbi(pci, CFG_TIMER_CTRL_MAX_FUNC_NUM_OFF, val);
 	}

 	config_gen3_gen4_eq_presets(pcie);

 	init_host_aspm(pcie);

 	if (!pcie->of_data->has_l1ss_exit_fix) {
 		val = dw_pcie_readl_dbi(pci, GEN3_RELATED_OFF);
 		val &= ~GEN3_RELATED_OFF_GEN3_ZRXDC_NONCOMPL;
 		dw_pcie_writel_dbi(pci, GEN3_RELATED_OFF, val);
 	}

 	pcie->pcie_cap_base = dw_pcie_find_capability(&pcie->pci,
 						      PCI_CAP_ID_EXP);

 	/* Clear Slot Clock Configuration bit if SRNS configuration */
 	if (pcie->enable_srns) {
 		val_16 = dw_pcie_readw_dbi(pci, pcie->pcie_cap_base +
 					   PCI_EXP_LNKSTA);
 		val_16 &= ~PCI_EXP_LNKSTA_SLC;
 		dw_pcie_writew_dbi(pci, pcie->pcie_cap_base + PCI_EXP_LNKSTA,
 				   val_16);
 	}

 	clk_set_rate(pcie->core_clk, GEN4_CORE_CLK_FREQ);

 	val = (ep->msi_mem_phys & MSIX_ADDR_MATCH_LOW_OFF_MASK);
 	val |= MSIX_ADDR_MATCH_LOW_OFF_EN;
 	dw_pcie_writel_dbi(pci, MSIX_ADDR_MATCH_LOW_OFF, val);
 	val = (upper_32_bits(ep->msi_mem_phys) & MSIX_ADDR_MATCH_HIGH_OFF_MASK);
 	dw_pcie_writel_dbi(pci, MSIX_ADDR_MATCH_HIGH_OFF, val);

 	ret = dw_pcie_ep_init_registers(ep);
 	if (ret) {
 		dev_err(dev, "Failed to complete initialization: %d\n", ret);
 		goto fail_init_complete;
 	}

 	pci_epc_init_notify(ep->epc);

 	/* Program the private control to allow sending LTR upstream */
 	if (pcie->of_data->has_ltr_req_fix) {
 		val = appl_readl(pcie, APPL_LTR_MSG_2);
 		val |= APPL_LTR_MSG_2_LTR_MSG_REQ_STATE;
 		appl_writel(pcie, val, APPL_LTR_MSG_2);
 	}

 	/* Enable LTSSM */
 	val = appl_readl(pcie, APPL_CTRL);
 	val |= APPL_CTRL_LTSSM_EN;
 	appl_writel(pcie, val, APPL_CTRL);

 	pcie->ep_state = EP_STATE_ENABLED;
 	dev_dbg(dev, "Initialization of endpoint is completed\n");

 	return;

 fail_init_complete:
 	reset_control_assert(pcie->core_rst);
 	tegra_pcie_disable_phy(pcie);
 fail_phy:
 	reset_control_assert(pcie->core_apb_rst);
 fail_core_apb_rst:
 	clk_disable_unprepare(pcie->core_clk);
 fail_core_clk_enable:
 	tegra_pcie_bpmp_set_pll_state(pcie, false);
 fail_pll_init:
 	tegra_pcie_bpmp_set_ctrl_state(pcie, false);
 fail_set_ctrl_state:
 	pm_runtime_put_sync(dev);
 }



